rce": "MED", "fullTextUrlList": {"fullTextUrl": [{"availability": "Subscription required", "availabilityCode": "S", "documentStyle": "doi", "site": "DOI", "url": "https://doi.org/10.2196/86633"}, {"availability": "Open access", "availabilityCode": "OA", "documentStyle": "html", "site": "Europe_PMC", "url": "https://europepmc.org/articles/PMC13200768"}, {"availability": "Open access", "availabilityCode": "OA", "documentStyle": "pdf", "site": "Europe_PMC", "url": "https://europepmc.org/articles/PMC13200768?pdf=render"}]}}, {"title": "Autonomous artificial intelligence, scientific research, and human values.", "abstract": "During the initial stage of AI's incorporation into scientific research, AI systems have functioned predominantly as tools under direct human supervision and control. However, AI incorporation into scientific research is now entering a stage in which AI Agents perform research tasks with partial autonomy while remaining under human supervision and control. In the not-too-distant future, a third stage may arise when autonomous AI systems conduct their own research and generate knowledge without human supervision or control. While the second and third stages of AI-augmented research may offer substantial benefits for science and society, they also create novel ethical issues, including (1) Conducting immoral research that may harm humans and other forms of life; (2) Increasing rate of biased, erroneous and deceptive research; (3) Confidentiality challenges; (4) Overreliance on AI; (5) Diffusion of responsibility and accountability; (6) Deskilling; (7) Job losses; (8) AI-generated research beyond human comprehension; and (9) Erosion of trust. We suggest specific solutions to minimize the negative consequences of these issues and offer proposals for ensuring that incorporation of AI into scientific research supports human values.", "doi": "10.1007/s43681-025-00908-0", "pmid": "41768290", "pmcid": "PMC12948163", "source": "MED", "fullTextUrlList": {"fullTextUrl": [{"availability": "Subscription required", "availabilityCode": "S", "documentStyle": "doi", "site": "DOI", "url": "https://doi.org/10.1007/s43681-025-00908-0"}, {"availability": "Open access", "availabilityCode": "OA", "documentStyle": "html", "site": "Europe_PMC", "url": "https://europepmc.org/articles/PMC12948163"}, {"availability": "Open access", "availabilityCode": "OA", "documentStyle": "pdf", "site": "Europe_PMC", "url": "https://europepmc.org/articles/PMC12948163?pdf=render"}]}}]", "excerpt_truncated": true, "source_sha256": "276f73c7f2c8674283337ed6a070d976ad9e8d204ef20f493927dced40b4582d", "verification_required": true, "topic_domain": "assumption_challenge", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.1007/s10676-026-09888-z", "doi:10.2196/86633", "doi:10.1007/s43681-025-00908-0", "pmc:PMC12827370", "pmc:PMC13200768", "pmc:PMC12948163"], "source_candidates": ["https://doi.org/10.1007/s10676-026-09888-z", "https://europepmc.org/articles/PMC12827370", "https://europepmc.org/articles/PMC12827370?pdf=render", "https://doi.org/10.2196/86633", "https://europepmc.org/articles/PMC13200768", "https://europepmc.org/articles/PMC13200768?pdf=render", "https://doi.org/10.1007/s43681-025-00908-0", "https://europepmc.org/articles/PMC12948163"], "source_candidate_identities": {}}

